async def act(page):
    # Locate the Bestsellers tabpanel and the table within it
    bestsellers_tabpanel = page.get_by_role('tabpanel', name='The information in this tab has been changed. This tab contains invalid data. Please resolve this before saving. Loading... Bestsellers')
    table = bestsellers_tabpanel.get_by_role('table').first

    # Get all rows in the table, skipping the header row
    rows = await table.get_by_role('row').all()
    products_data = []

    for row in rows:
        # Skip the header row by checking if it contains 'Product Price Quantity'
        row_text = await row.text_content()
        if 'Product' in row_text and 'Price' in row_text and 'Quantity' in row_text:
            continue
        # Extract cells
        cells = await row.get_by_role('cell').all()
        if len(cells) >= 3:
            product_name = await cells[0].text_content()
            quantity_str = await cells[2].text_content()
            # Convert quantity to integer for sorting
            try:
                quantity = int(quantity_str.strip())
            except ValueError:
                continue  # Skip if quantity is not a number
            products_data.append((product_name.strip(), quantity))

    # Sort by quantity in descending order
    products_data.sort(key=lambda x: x[1], reverse=True)

    # Get top 2 product names
    top_products = [product for product, _ in products_data[:2]]

    # Return the result as a string
    result = ', '.join(top_products) if top_products else 'No products found'
    return result
